            test("energy storage simulation is pure",new Runnable(){public void run(){setupEnergy();LegacyEnergy.State s=fluidNode(-1).energy;check(s.receive(1000,true)==1000&&s.stored()==0,"simulated charge");s.receive(1000,false);check(s.extract(500,true)==500&&s.stored()==1000,"simulated discharge");}});
