    private void test(String name,Runnable body){total++;JsonObject result=new JsonObject();result.addProperty("name",name);try{reset();body.run();passed++;result.addProperty("passed",true);}catch(Throwable error){result.addProperty("passed",false);result.addProperty("error",error.toString());error.printStackTrace();}results.add(result);}
    private void reset(){LegacyPL4.energyEnabled=true;LegacyPL4.energyRate=400;LegacyPL4.manualEnergy=40;LegacyPL4.fluidsEnabled=true;LegacyPL4.fluidRate=250;LegacyPL4.enabled=true;LegacyPL4.nodeLimit=256;LegacyPL4.slotLimit=256;LegacyPL4.itemRate=8;for(int x=-2;x<=4;x++)for(int y=199;y<=202;y++)for(int z=-1;z<=1;z++){world.getChunkFromBlockCoords(new BlockPos(x,y,z));world.setBlockToAir(new BlockPos(x,y,z));}for(EntityItem item:world.getEntitiesWithinAABB(EntityItem.class,new AxisAlignedBB(-3,198,-3,6,204,3)))item.setDead();world.setBlockState(export,LegacyPL4.EXPORT.getDefaultState(),3);world.setBlockState(cable,LegacyPL4.CABLE.getDefaultState(),3);world.setBlockState(sink,LegacyPL4.IMPORT.getDefaultState(),3);for(BlockPos p:new BlockPos[]{export,cable,sink})node(p).owner=OWNER.toString();node(export).side=4;node(sink).side=5;world.setBlockState(export.west(),Blocks.CHEST.getDefaultState(),3);world.setBlockState(sink.east(),Blocks.CHEST.getDefaultState(),3);}
    private LegacyTile node(BlockPos p){return (LegacyTile)world.getTileEntity(p);}
    private TileEntityChest source(){return (TileEntityChest)world.getTileEntity(export.west());}
    private TileEntityChest destination(){return (TileEntityChest)world.getTileEntity(sink.east());}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}

    private static FluidStack water(int amount){return new FluidStack(FluidRegistry.WATER,amount);}
    private void setupFluids(){fluidBlock(-1,LegacyPL4.TANK);fluidBlock(0,LegacyPL4.FLUID_EXPORT);fluidBlock(2,LegacyPL4.FLUID_IMPORT);fluidBlock(3,LegacyPL4.TANK);for(int x:new int[]{-1,0,1,2,3})fluidNode(x).owner=fluidOwner();fluidNode(0).side=4;fluidNode(2).side=5;}

    private String fluidOwner(){return OWNER.toString();}
    private EntityPlayer fluidPlayer(){return FakePlayerFactory.get(world,new GameProfile(OWNER,"Owner"));}
    private LegacyTile fluidNode(int x){return (LegacyTile)world.getTileEntity(new BlockPos(x,200,0));}
    private void fluidBlock(int x,LegacyBlock block){world.setBlockState(new BlockPos(x,200,0),block.getDefaultState(),3);}
    private void fluidAir(int x,int y){world.setBlockToAir(new BlockPos(x,y,0));}
    private void fluidPower(int x){world.setBlockState(new BlockPos(x,201,0),Blocks.REDSTONE_BLOCK.getDefaultState(),3);}
    private NBTTagCompound saveFluid(LegacyTile tile){return tile.writeToNBT(new NBTTagCompound());}
    private ItemStack waterBucket(){return new ItemStack(Items.WATER_BUCKET);}
    private ItemStack emptyBucket(){return new ItemStack(Items.BUCKET);}
    private int fluidCells(){int n=0;for(EntityItem item:world.getEntitiesWithinAABB(EntityItem.class,new AxisAlignedBB(-3,198,-3,6,204,3)))if(!item.isDead&&item.getItem().getItem()==LegacyPL4.FLUID_CELL&&item.getItem().getTagCompound().getCompoundTag("Contents").getInteger("Amount")==1234)n++;return n;}
