    private EntityPlayer wirelessPlayer(){EntityPlayer p=fluidPlayer();p.setPosition(.5,200,3.5);for(int i=0;i<36;i++)p.inventory.setInventorySlotContents(i,ItemStack.EMPTY);p.inventory.currentItem=0;p.inventory.setInventorySlotContents(0,new ItemStack(LegacyPL4.WIRELESS_STORAGE));check(LegacyWirelessStorage.bind(p,wirelessTool(p),fluidNode(0)),"owner bound tool");return p;}
