    private int wirelessIron(EntityPlayer p){int n=0;for(int i=0;i<36;i++){ItemStack stack=p.inventory.getStackInSlot(i);if(LegacyTile.STACKS.same(readerStack(1),stack))n+=readerCount(stack);}return n;}
