    private void readerDisplay(){fluidBlock(0,LegacyPL4.DISPLAY);fluidBlock(2,LegacyPL4.ITEM_READER);fluidNode(0).owner=fluidOwner();fluidNode(2).owner=fluidOwner();fluidNode(2).side=5;}
