        @Override public <T> T getCapability(net.minecraftforge.common.capabilities.Capability<T> cap,net.minecraft.util.EnumFacing side){return cap==net.minecraftforge.items.CapabilityItemHandler.ITEM_HANDLER_CAPABILITY?net.minecraftforge.items.CapabilityItemHandler.ITEM_HANDLER_CAPABILITY.cast(new net.minecraftforge.items.wrapper.InvWrapper(backing){}):super.getCapability(cap,side);}
